"use client";
import * as React from "react"
import useEmblaCarousel from "embla-carousel-react";

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react"

const CarouselContext = React.createContext(null)

function useCarousel() {
  const context = React.useContext(CarouselContext)

  if (!context) {
    throw new Error("useCarousel must be used within a <Carousel />")
  }

  return context
}

function Carousel({
  orientation = "horizontal",
  opts,
  setApi,
  plugins,
  className,
  children,
  ...props
}) {
  const [carouselRef, api] = useEmblaCarousel({
    ...opts,
    axis: orientation === "horizontal" ? "x" : "y",
  }, plugins)
  const [canScrollPrev, setCanScrollPrev] = React.useState(false)
  const [canScrollNext, setCanScrollNext] = React.useState(false)

  const onSelect = React.useCallback((api) => {
    if (!api) return
    setCanScrollPrev(api.canScrollPrev())
    setCanScrollNext(api.canScrollNext())
  }, [])

  const scrollPrev = React.useCallback(() => {
    api?.scrollPrev()
  }, [api])

  const scrollNext = React.useCallback(() => {
    api?.scrollNext()
  }, [api])

  const handleKeyDown = React.useCallback((event) => {
    if (event.key === "ArrowLeft") {
      event.preventDefault()
      scrollPrev()
    } else if (event.key === "ArrowRight") {
      event.preventDefault()
      scrollNext()
    }
  }, [scrollPrev, scrollNext])

  React.useEffect(() => {
    if (!api || !setApi) return
    setApi(api)
  }, [api, setApi])

  React.useEffect(() => {
    if (!api) return
    onSelect(api)
    api.on("reInit", onSelect)
    api.on("select", onSelect)

    return () => {
      api?.off("select", onSelect)
    };
  }, [api, onSelect])

  return (
    <CarouselContext.Provider
      value={{
        carouselRef,
        api: api,
        opts,
        orientation:
          orientation || (opts?.axis === "y" ? "vertical" : "horizontal"),
        scrollPrev,
        scrollNext,
        canScrollPrev,
        canScrollNext,
      }}>
      <div
        onKeyDownCapture={handleKeyDown}
        className={cn("relative", className)}
        role="region"
        aria-roledescription="carousel"
        data-slot="carousel"
        {...props}>
        {children}
      </div>
    </CarouselContext.Provider>
  );
}

function CarouselContent({
  className,
  ...props
}) {
  const { carouselRef, orientation } = useCarousel()

  return (
    <div
      ref={carouselRef}
      className="overflow-hidden"
      data-slot="carousel-content">
      <div
        className={cn(
          "flex",
          orientation === "horizontal" ? "-ml-4" : "-mt-4 flex-col",
          className
        )}
        {...props} />
    </div>
  );
}

function CarouselItem({
  className,
  ...props
}) {
  const { orientation } = useCarousel()

  return (
    <div
      role="group"
      aria-roledescription="slide"
      data-slot="carousel-item"
      className={cn(
        "min-w-0 shrink-0 grow-0 basis-full",
        orientation === "horizontal" ? "pl-4" : "pt-4",
        className
      )}
      {...props} />
  );
}

function CarouselPrevious({
  className,
  variant = "outline",
  size = "icon-sm",
  ...props
}) {
  const { orientation, scrollPrev, canScrollPrev } = useCarousel()

  return (
    <Button
      data-slot="carousel-previous"
      variant={variant}
      size={size}
      className={cn("absolute touch-manipulation rounded-full", orientation === "horizontal"
        ? "inset-y-0 -left-12 my-auto"
        : "-top-12 left-1/2 -translate-x-1/2 rotate-90", className)}
      disabled={!canScrollPrev}
      onClick={scrollPrev}
      {...props}>
      <ChevronLeftIcon />
      <span className="sr-only">Previous slide</span>
    </Button>
  );
}

function CarouselNext({
  className,
  variant = "outline",
  size = "icon-sm",
  ...props
}) {
  const { orientation, scrollNext, canScrollNext } = useCarousel()

  return (
    <Button
      data-slot="carousel-next"
      variant={variant}
      size={size}
      className={cn("absolute touch-manipulation rounded-full", orientation === "horizontal"
        ? "inset-y-0 -right-12 my-auto"
        : "-bottom-12 left-1/2 -translate-x-1/2 rotate-90", className)}
      disabled={!canScrollNext}
      onClick={scrollNext}
      {...props}>
      <ChevronRightIcon />
      <span className="sr-only">Next slide</span>
    </Button>
  );
}

export { Carousel, CarouselContent, CarouselItem, CarouselPrevious, CarouselNext, useCarousel };

'use client';

import Image from 'next/image';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';
import { Button } from '@/components/ui/button';
import {
  Carousel,
  CarouselContent,
  CarouselItem,
} from '@/components/ui/carousel';
import {
  normalizeSlideshowSlides,
  shouldRunSlideshowAutoplay,
  slideshowInterval,
  wrappedSlideIndex,
} from '@/lib/slideshow.mjs';
import styles from './directus-page.module.css';

export default function SlideshowBlock({ item }) {
  const slides = useMemo(() => normalizeSlideshowSlides(item.slides), [item.slides]);
  const [api, setApi] = useState(null);
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(!item.autoplay);
  const [reducedMotion, setReducedMotion] = useState(true);
  const interval = slideshowInterval(item.interval);

  const goTo = (next) => {
    if (!api || !slides.length) return;
    api.scrollTo(wrappedSlideIndex(next, slides.length));
  };

  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const updatePreference = () => setReducedMotion(query.matches);
    updatePreference();
    query.addEventListener?.('change', updatePreference);
    return () => query.removeEventListener?.('change', updatePreference);
  }, []);

  useEffect(() => {
    if (!api) return undefined;
    const onSelect = () => setIndex(api.selectedScrollSnap());
    onSelect();
    api.on('select', onSelect);
    api.on('reInit', onSelect);
    return () => {
      api.off('select', onSelect);
      api.off('reInit', onSelect);
    };
  }, [api]);

  useEffect(() => {
    if (!api || !shouldRunSlideshowAutoplay({
      autoplay: item.autoplay,
      paused,
      reducedMotion,
      slideCount: slides.length,
    })) return undefined;
    const timer = window.setInterval(() => {
      if (api.canScrollNext()) api.scrollNext();
      else api.scrollTo(0);
    }, interval);
    return () => window.clearInterval(timer);
  }, [api, interval, item.autoplay, paused, reducedMotion, slides.length]);

  if (!slides.length) return null;
  const current = slides[index] || slides[0];
  const showCaptions = item.show_captions !== false;
  const hasCaptions = slides.some((slide) => slide.caption || slide.credit);
  const captionText = (slide) => (
    <>
      {slide.caption}
      {slide.caption && slide.credit && ' / '}
      {slide.credit}
    </>
  );

  return (
    <section
      aria-label={item.title || 'Image slideshow'}
      className={`${styles.block} ${styles.slideshowBlock}`}
      data-theme={item.theme || 'paper'}
      data-variant={item.variant || 'editorial'}
    >
      <div className={styles.slideshowHeading}>
        <div>
          {item.eyebrow && <p className={styles.eyebrow}>{item.eyebrow}</p>}
          {item.title && <h2>{item.title}</h2>}
        </div>
        {item.dek && <p className={styles.dek}>{item.dek}</p>}
      </div>

      <Carousel
        aria-label={item.title || 'Image slideshow'}
        className={styles.slideshowStage}
        opts={{ align: 'start', loop: false }}
        setApi={setApi}
      >
        <CarouselContent className={styles.slideshowTrack}>
          {slides.map((slide, slideIndex) => (
            <CarouselItem key={slide.key}>
              <div className={styles.slideshowImage}>
                <Image
                  alt={slide.alt}
                  fill
                  loading={slideIndex === 0 ? 'eager' : 'lazy'}
                  sizes="(max-width: 900px) 100vw, 88vw"
                  src={slide.src}
                />
              </div>
            </CarouselItem>
          ))}
        </CarouselContent>

        <div className={styles.slideshowControls}>
          <div>
            <Button
              aria-label="Previous slide"
              className="rounded-none"
              onClick={() => goTo(index - 1)}
              size="icon-lg"
              type="button"
              variant="outline"
            >
              <ChevronLeft aria-hidden="true" />
            </Button>
            <Button
              aria-label="Next slide"
              className="rounded-none"
              onClick={() => goTo(index + 1)}
              size="icon-lg"
              type="button"
              variant="outline"
            >
              <ChevronRight aria-hidden="true" />
            </Button>
          </div>
          {item.show_counter !== false && (
            <p aria-live={item.autoplay && !paused ? 'off' : 'polite'} className={styles.slideshowCounter}>
              {String(index + 1).padStart(2, '0')} / {String(slides.length).padStart(2, '0')}
            </p>
          )}
          {item.autoplay && (
            <Button
              aria-label={paused ? 'Play slideshow' : 'Pause slideshow'}
              className={`${styles.slideshowPlayback} rounded-none`}
              onClick={() => setPaused((value) => !value)}
              size="sm"
              type="button"
              variant="outline"
            >
              {paused ? 'Play' : 'Pause'}
            </Button>
          )}
        </div>

        {showCaptions && hasCaptions && (
          <div aria-live="polite" className={styles.slideshowCaptionFrame}>
            {slides.map((slide) => (
              <p
                aria-hidden="true"
                className={`${styles.slideshowCaption} ${styles.slideshowCaptionSizer}`}
                key={`${slide.key}-caption-size`}
              >
                {captionText(slide)}
              </p>
            ))}
            <p className={styles.slideshowCaption}>
              {captionText(current)}
            </p>
          </div>
        )}
      </Carousel>

      {(item.variant === 'thumbnail-rail') && (
        <div aria-label="Choose slide" className={styles.slideshowThumbnails}>
          {slides.map((slide, slideIndex) => (
            <Button
              aria-current={slideIndex === index ? 'true' : undefined}
              aria-label={`Show slide ${slideIndex + 1}`}
              className="rounded-none p-0"
              key={slide.key}
              onClick={() => goTo(slideIndex)}
              type="button"
              variant="ghost"
            >
              <Image alt="" fill sizes="120px" src={slide.src} />
            </Button>
          ))}
        </div>
      )}
    </section>
  );
}

export const MAX_SLIDES = 12;
export const MINIMUM_AUTOPLAY_INTERVAL_MS = 4000;
export const DEFAULT_AUTOPLAY_INTERVAL_MS = 6000;

export function slideshowAssetUrl(file) {
  if (!file) return '';
  if (typeof file === 'string') {
    if (file.startsWith('/') || file.startsWith('http://') || file.startsWith('https://')) return file;
    return `/api/assets/${file}`;
  }
  return slideshowAssetUrl(file.id || file.image || file.file);
}

export function normalizeSlideshowSlides(value) {
  if (!Array.isArray(value)) return [];
  return value.slice(0, MAX_SLIDES).map((slide, index) => {
    if (typeof slide === 'string') {
      return {
        src: slideshowAssetUrl(slide),
        alt: '',
        caption: '',
        credit: '',
        key: `${slide}-${index}`,
      };
    }
    if (!slide || typeof slide !== 'object') return null;
    const src = slideshowAssetUrl(slide.image || slide.file || slide.id);
    if (!src) return null;
    return {
      src,
      alt: slide.image_alt || slide.alt || '',
      caption: slide.caption || '',
      credit: slide.credit || '',
      key: `${slide.id || slide.image || slide.file || 'slide'}-${index}`,
    };
  }).filter(Boolean);
}

export function slideshowInterval(value) {
  return Math.max(Number(value) || DEFAULT_AUTOPLAY_INTERVAL_MS, MINIMUM_AUTOPLAY_INTERVAL_MS);
}

export function shouldRunSlideshowAutoplay({
  autoplay,
  paused,
  reducedMotion,
  slideCount,
}) {
  return Boolean(autoplay && !paused && !reducedMotion && slideCount > 1);
}

export function wrappedSlideIndex(index, slideCount) {
  if (!slideCount) return 0;
  return ((index % slideCount) + slideCount) % slideCount;
}

.page {
  min-height: 100vh;
  background: var(--paper);
  color: var(--ink);
}

.componentFrame {
  --component-inline: var(--space-8, 64px);
  --component-block: var(--space-9, 96px);
  --component-gap: var(--space-6, 32px);
  display: contents;
}

.componentFrame[data-spacing='compact'] {
  --component-inline: var(--space-5, 24px);
  --component-block: var(--space-8, 64px);
  --component-gap: var(--space-4, 16px);
}

.componentFrame[data-spacing='generous'] {
  --component-inline: var(--space-9, 96px);
  --component-block: var(--space-10, 128px);
  --component-gap: var(--space-7, 48px);
}

.pageHeader,
.block {
  padding: var(--component-block, clamp(64px, 9vw, 132px)) var(--component-inline, clamp(24px, 6vw, 88px));
  border-bottom: 1px solid var(--rule);
}

.pageHeader {
  min-height: 58vh;
  display: grid;
  align-content: end;
}

.pageHeader h1,
.hero h1 {
  max-width: 12ch;
  margin: var(--space-3, 12px) 0 0;
  font-family: var(--serif);
  font-size: clamp(64px, 9vw, 132px);
  font-weight: 400;
  letter-spacing: -0.05em;
  line-height: 0.86;
}

.eyebrow {
  margin: 0 0 var(--space-4, 16px);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.dek {
  max-width: 48ch;
  margin: var(--space-5, 24px) 0 0;
  color: var(--ink-60);
  font-size: clamp(17px, 2vw, 21px);
  line-height: 1.6;
}

.block[data-theme='dark'],
.block[data-theme='ink'] {
  background: var(--ink);
  color: var(--paper);
}

.block[data-theme='dark'] .dek,
.block[data-theme='ink'] .dek {
  color: var(--ink-20);
}

.block[data-theme='paper-2'],
.block[data-theme='stone'] {
  background: var(--paper-2);
}

.hero {
  min-height: 82vh;
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(320px, 0.95fr);
  gap: var(--component-gap, 32px);
  align-items: center;
}

.heroCopy {
  position: relative;
  z-index: 1;
}

.heroImage {
  position: relative;
  min-height: 62vh;
  overflow: hidden;
  background: var(--paper-2);
}

.heroImage img,
.mediaImage img,
.cardImage img {
  object-fit: cover;
}

.hero[data-variant='cover'] {
  position: relative;
  min-height: 92vh;
  display: grid;
  grid-template-columns: 1fr;
  align-items: end;
  overflow: hidden;
  color: var(--paper);
}

.hero[data-variant='cover'] .heroCopy {
  max-width: 820px;
}

.hero[data-variant='cover'] .heroImage {
  position: absolute;
  inset: 0;
  min-height: 0;
}

.hero[data-variant='cover'] .heroImage::after {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, rgb(24 25 24 / 78%), rgb(24 25 24 / 12%));
  content: '';
}

.hero[data-variant='minimal'] {
  min-height: 62vh;
  grid-template-columns: 1fr;
}

.hero[data-variant='minimal'] .heroImage {
  display: none;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3, 12px);
  margin-top: var(--space-6, 32px);
}

.primaryAction,
.secondaryAction {
  padding: var(--space-4, 16px) var(--space-5, 24px);
  border: 1px solid currentColor;
  color: inherit;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-decoration: none;
  text-transform: uppercase;
}

.primaryAction {
  background: var(--ink);
  color: var(--paper);
}

.block[data-theme='dark'] .primaryAction,
.block[data-theme='ink'] .primaryAction {
  background: var(--paper);
  color: var(--ink);
}

.textBlock {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(300px, 1.1fr);
  gap: var(--component-gap, 32px);
}

.textBlock[data-variant='centered'] {
  display: block;
  text-align: center;
}

.textBlock[data-variant='centered'] .blockHeading,
.textBlock[data-variant='centered'] .blockBody {
  max-width: 760px;
  margin-inline: auto;
}

.textBlock[data-variant='left'] {
  display: block;
}

.textBlock[data-variant='left'] .blockHeading,
.textBlock[data-variant='left'] .blockBody {
  max-width: 760px;
}

.blockHeading h2,
.quoteBlock h2,
.ctaBlock h2 {
  max-width: 14ch;
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(44px, 6vw, 88px);
  font-weight: 400;
  letter-spacing: -0.035em;
  line-height: 0.98;
}

.blockBody {
  font-size: 17px;
  line-height: 1.7;
}

.blockBody > p {
  margin: 0;
}

.bodyList {
  margin: 0;
  padding: 0;
  list-style: none;
  border-top: 1px solid currentColor;
}

.bodyList li {
  padding: var(--space-4, 16px) 0;
  border-bottom: 1px solid color-mix(in srgb, currentColor 24%, transparent);
}

.bodyStack {
  display: grid;
  gap: var(--space-6, 32px);
}

.bodyStack article {
  padding-top: var(--space-5, 24px);
  border-top: 1px solid var(--rule);
}

.bodyStack h3 {
  margin: 0;
  font-family: var(--serif);
  font-size: 30px;
  font-weight: 500;
}

.bodyStack p {
  margin: var(--space-3, 12px) 0 0;
}

.definitionList {
  margin: 0;
}

.definitionList > div {
  display: grid;
  grid-template-columns: 160px 1fr;
  gap: var(--space-5, 24px);
  padding: var(--space-4, 16px) 0;
  border-bottom: 1px solid var(--rule);
}

.definitionList dt {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.definitionList dd {
  margin: 0;
}

.mediaBlock .blockHeading {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 0.55fr);
  gap: clamp(40px, 8vw, 120px);
}

.mediaFigure {
  margin: clamp(48px, 7vw, 88px) 0 0;
}

.mediaImage {
  position: relative;
  aspect-ratio: 3 / 2;
  overflow: hidden;
  background: var(--paper-2);
}

.mediaBlock[data-variant='full-width'] {
  padding-inline: 0;
}

.mediaBlock[data-variant='full-width'] .blockHeading,
.mediaBlock[data-variant='full-width'] figcaption {
  margin-inline: clamp(24px, 6vw, 88px);
}

.mediaBlock[data-variant='full-width'] .mediaImage {
  aspect-ratio: 16 / 8;
}

.mediaBlock[data-variant='gallery'] .mediaFigure {
  display: none;
}

.mediaFigure figcaption {
  max-width: 64ch;
  margin-top: var(--space-3, 12px);
  color: var(--ink-60);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  line-height: 1.5;
  text-transform: uppercase;
}

.galleryGrid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-5, 24px);
  margin-top: var(--space-5, 24px);
}

.galleryGrid figure {
  margin: 0;
}

.galleryImage {
  position: relative;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  background: var(--paper-2);
}

.galleryImage img {
  object-fit: cover;
}

.galleryGrid figcaption {
  margin-top: var(--space-3, 12px);
  color: var(--ink-60);
  font-size: 12px;
  line-height: 1.5;
}

.quoteBlock blockquote {
  max-width: 18ch;
  margin: var(--space-8, 64px) 0 var(--space-5, 24px);
  font-family: var(--serif);
  font-size: clamp(48px, 7vw, 100px);
  font-style: italic;
  line-height: 0.98;
}

.quoteBlock cite {
  font-family: var(--mono);
  font-size: 10px;
  font-style: normal;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.listingBlock .blockHeading {
  max-width: 900px;
}

.cardGrid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(36px, 4vw, 56px) clamp(24px, 3vw, 36px);
  align-items: start;
  margin-top: clamp(56px, 6vw, 80px);
}

.listingBlock[data-variant='featured'] .card:first-child {
  grid-column: span 2;
}

.listingBlock[data-variant='featured'] .card:first-child .cardImage {
  aspect-ratio: 16 / 8;
}

.listingBlock[data-variant='archive'] .cardGrid {
  grid-template-columns: 1fr;
  gap: 0;
}

.listingBlock[data-variant='archive'] .card {
  padding: var(--space-5, 24px) 0;
}

.listingBlock[data-variant='archive'] .cardLink {
  display: grid;
  grid-template-columns: minmax(120px, 0.35fr) minmax(0, 1fr);
  gap: var(--space-5, 24px);
  align-items: baseline;
}

.listingBlock[data-variant='archive'] .cardImage,
.listingBlock[data-variant='archive'] .cardLink > p:last-child {
  display: none;
}

.card {
  padding-top: var(--space-5, 24px);
  border-top: 1px solid currentColor;
}

.cardLink {
  color: inherit;
  text-decoration: none;
}

.cardImage {
  position: relative;
  aspect-ratio: 4 / 3;
  margin-bottom: var(--space-5, 24px);
  overflow: hidden;
  background: var(--paper-2);
}

.card h3 {
  margin: var(--space-3, 12px) 0 0;
  font-family: var(--serif);
  font-size: 30px;
  font-weight: 500;
  line-height: 1.08;
}

.cardLink > p:not(.eyebrow) {
  margin: var(--space-3, 12px) 0 0;
  color: var(--ink-60);
  line-height: 1.55;
}

.listingBlock[data-variant='archive'] .card h3 {
  margin: 0;
}

.emptyListing {
  color: var(--ink-60);
}

.ctaBlock {
  text-align: center;
}

.ctaBlock h2,
.ctaBlock .dek {
  margin-inline: auto;
}

.ctaBlock .actions {
  justify-content: center;
}

.ctaBlock[data-variant='band'] {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: var(--space-6, 32px);
  align-items: center;
  padding-block: clamp(40px, 5vw, 72px);
  text-align: left;
}

.ctaBlock[data-variant='band'] .eyebrow,
.ctaBlock[data-variant='band'] .dek {
  grid-column: 1;
  margin-inline: 0;
}

.ctaBlock[data-variant='band'] .actions {
  grid-column: 2;
  grid-row: 1 / span 3;
  justify-content: flex-end;
  margin-top: 0;
}

.slideshowBlock {
  overflow: hidden;
}

.slideshowBlock:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -6px;
}

.slideshowHeading {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 0.55fr);
  gap: clamp(40px, 8vw, 120px);
  margin-bottom: clamp(36px, 6vw, 72px);
}

.slideshowHeading h2 {
  max-width: 14ch;
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(44px, 6vw, 88px);
  font-weight: 400;
  letter-spacing: -0.035em;
  line-height: 0.98;
}

.slideshowStage {
  max-width: 1280px;
  margin-inline: auto;
}

.slideshowImage {
  position: relative;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: var(--paper-2);
}

.slideshowImage img {
  object-fit: cover;
}

.slideshowBlock[data-variant='editorial'] .slideshowStage {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, 0.32fr);
  align-items: end;
}

.slideshowBlock[data-variant='editorial'] .slideshowControls,
.slideshowBlock[data-variant='editorial'] .slideshowCaptionFrame {
  grid-column: 2;
  padding-left: var(--space-6, 32px);
}

.slideshowBlock[data-variant='full-width'] {
  padding-inline: 0;
}

.slideshowBlock[data-variant='full-width'] .slideshowHeading,
.slideshowBlock[data-variant='full-width'] .slideshowControls,
.slideshowBlock[data-variant='full-width'] .slideshowCaptionFrame {
  margin-inline: clamp(24px, 6vw, 88px);
}

.slideshowBlock[data-variant='full-width'] .slideshowStage {
  max-width: none;
}

.slideshowBlock[data-variant='full-width'] .slideshowImage {
  aspect-ratio: 16 / 8;
}

.slideshowControls {
  display: flex;
  gap: var(--space-4, 16px);
  align-items: center;
  justify-content: space-between;
  padding-top: var(--space-4, 16px);
}

.slideshowControls button,
.slideshowThumbnails button {
  border: 1px solid currentColor;
  background: transparent;
  color: inherit;
  cursor: pointer;
}

.slideshowControls button {
  min-width: 44px;
  min-height: 44px;
  margin-right: var(--space-2, 8px);
  font-size: 18px;
}

.slideshowControls button:focus-visible,
.slideshowThumbnails button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.slideshowCounter,
.slideshowPlayback,
.slideshowCaption {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  line-height: 1.6;
  text-transform: uppercase;
}

.slideshowPlayback {
  padding: var(--space-2, 8px) var(--space-3, 12px);
}

.slideshowCaption {
  margin: var(--space-3, 12px) 0 0;
  color: var(--ink-60);
}

.slideshowCaptionFrame {
  display: grid;
}

.slideshowCaptionFrame .slideshowCaption {
  grid-area: 1 / 1;
}

.slideshowCaptionSizer {
  visibility: hidden;
}

.slideshowThumbnails {
  display: flex;
  gap: var(--space-3, 12px);
  max-width: 1280px;
  margin: var(--space-4, 16px) auto 0;
  overflow-x: auto;
  padding: var(--space-1, 4px);
}

.slideshowThumbnails button {
  position: relative;
  flex: 0 0 112px;
  aspect-ratio: 4 / 3;
  opacity: 0.58;
}

.slideshowThumbnails button[aria-current='true'] {
  opacity: 1;
  outline: 2px solid var(--accent);
}

.slideshowThumbnails img {
  object-fit: cover;
}

.podcastPlayerBlock {
  display: grid;
  gap: clamp(28px, 4vw, 48px);
  padding-block: clamp(56px, 7vw, 96px);
}

.podcastPlayerHeader {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 0.55fr);
  gap: clamp(40px, 8vw, 120px);
  align-items: end;
}

.podcastPlayerHeader h2 {
  max-width: 14ch;
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(44px, 6vw, 88px);
  font-weight: 400;
  letter-spacing: -0.035em;
  line-height: 0.98;
}

.podcastMeta {
  margin: var(--space-4, 16px) 0 0;
  color: var(--ink-60);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  line-height: 1.6;
  text-transform: uppercase;
}

.podcastPlayerShell {
  display: grid;
  gap: var(--space-4, 16px);
  align-items: stretch;
  padding: var(--space-5, 24px);
  border: 1px solid currentColor;
  background: var(--paper-2);
}

.mediaController {
  display: block;
  width: 100%;
  min-width: 0;
  --media-primary-color: var(--ink);
  --media-secondary-color: var(--paper);
  --media-background-color: var(--paper);
  --media-control-background: var(--paper);
  --media-control-hover-background: var(--paper-3);
  --media-range-track-background: var(--ink-20);
  --media-range-bar-color: var(--ink);
  --media-time-range-buffered-color: var(--ink-40);
}

.mediaControlBar {
  width: 100%;
  min-height: 52px;
  border: 1px solid var(--rule);
  background: var(--paper);
}

.mediaControllerPlaceholder {
  width: 100%;
  min-height: 52px;
  border: 1px solid var(--rule);
  background:
    linear-gradient(var(--ink), var(--ink)) 14px 50% / 10px 14px no-repeat,
    linear-gradient(var(--ink-20), var(--ink-20)) 40px 50% / calc(100% - 98px) 2px no-repeat,
    var(--paper);
}

.podcastPlayerActions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3, 12px);
  justify-content: flex-end;
}

.podcastPlayerActions a {
  gap: var(--space-2, 8px);
  border-color: currentColor;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.podcastTranscript {
  max-width: 78ch;
  border-top: 1px solid var(--rule);
  padding-top: var(--space-4, 16px);
  color: var(--ink-80);
  line-height: 1.7;
}

.podcastTranscript summary {
  cursor: pointer;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.podcastTranscript summary:focus-visible,
.podcastRelated a:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.podcastRelated {
  display: grid;
  grid-template-columns: minmax(180px, 0.28fr) minmax(0, 1fr);
  gap: var(--space-5, 24px);
  border-top: 1px solid var(--rule);
  padding-top: var(--space-4, 16px);
}

.podcastRelated > div {
  display: grid;
  gap: 0;
}

.podcastRelated a {
  display: flex;
  justify-content: space-between;
  gap: var(--space-5, 24px);
  padding: var(--space-4, 16px) 0;
  border-bottom: 1px solid var(--rule);
  color: inherit;
  text-decoration: none;
}

.podcastRelated span {
  font-family: var(--serif);
  font-size: 24px;
}

.podcastRelated small {
  color: var(--ink-60);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.podcastPlayerBlock[data-variant='compact'] .podcastPlayerHeader,
.podcastPlayerBlock[data-variant='sticky-bar'] .podcastPlayerHeader {
  display: block;
}

.podcastPlayerBlock[data-variant='compact'] .podcastPlayerHeader h2,
.podcastPlayerBlock[data-variant='sticky-bar'] .podcastPlayerHeader h2 {
  font-size: clamp(32px, 4vw, 52px);
}

.podcastPlayerBlock[data-variant='sticky-bar'] {
  position: sticky;
  bottom: 0;
  z-index: 20;
  padding-block: var(--space-5, 24px);
}

.podcastPlayerBlock[data-variant='sticky-bar'] .podcastPlayerShell {
  box-shadow: 0 -12px 32px color-mix(in srgb, var(--ink) 12%, transparent);
}

.slot[data-slot='related-content'] {
  background: var(--paper-2);
}

@media (max-width: 900px) {
  .hero,
  .textBlock,
  .mediaBlock .blockHeading,
  .slideshowHeading,
  .podcastPlayerHeader,
  .podcastPlayerShell,
  .podcastRelated {
    grid-template-columns: 1fr;
  }

  .hero {
    padding-top: 96px;
  }

  .heroImage {
    min-height: 54vw;
  }

  .cardGrid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ctaBlock[data-variant='band'] {
    display: block;
  }

  .ctaBlock[data-variant='band'] .actions {
    justify-content: flex-start;
    margin-top: var(--space-6, 32px);
  }

  .slideshowBlock[data-variant='editorial'] .slideshowStage {
    display: block;
  }

  .slideshowBlock[data-variant='editorial'] .slideshowControls,
  .slideshowBlock[data-variant='editorial'] .slideshowCaptionFrame {
    padding-left: 0;
  }

  .podcastPlayerActions {
    justify-content: flex-start;
  }
}

@media (max-width: 640px) {
  .componentFrame {
    --component-inline: var(--space-5, 24px);
  }

  .pageHeader,
  .block {
    padding-inline: var(--component-inline, 24px);
  }

  .cardGrid {
    grid-template-columns: 1fr;
  }

  .listingBlock[data-variant='featured'] .card:first-child {
    grid-column: auto;
  }

  .listingBlock[data-variant='archive'] .cardLink {
    grid-template-columns: 1fr;
    gap: var(--space-1, 4px);
  }

  .galleryGrid {
    grid-template-columns: 1fr;
  }

  .definitionList > div {
    grid-template-columns: 1fr;
    gap: var(--space-2, 8px);
  }
}
